/* From Uiverse.io by gharsh11032000 - Tags: form, login , login form, signin */
.__UIV_SCOPE__ .form-container {
  width: 350px;
  background-color: #fff;
  padding: 32px 24px;
  font-size: 14px;
  font-family: inherit;
  color: #212121;
  display: flex;
  flex-direction: column;
  gap: 24px;
  box-sizing: border-box;
  border-radius: 10px;
  box-shadow: 0px 0px 3px rgba(0, 0, 0, 0.084), 0px 2px 3px rgba(0, 0, 0, 0.168);
}

.__UIV_SCOPE__ .form-container button:active {
  scale: 0.95;
}

.__UIV_SCOPE__ .form-container .logo-container {
  margin-bottom: 12px;
  text-align: center;
  font-weight: 700;
  font-size: 20px;
}

.__UIV_SCOPE__ .form-container .social-buttons {
  display: flex;
  justify-content: center;
  margin-bottom: 20px;
  flex-direction: column;
  gap: 12px;
  align-items: center;
}

.__UIV_SCOPE__ .form-container .social-button {
  display: flex;
  justify-content: center;
  align-items: center;
  width: 100%;
  font-family: inherit;
  color: #fff;
  border: none;
  padding: 12px 16px;
  gap: 8px;
  cursor: pointer;
  border-radius: 6px;
  box-shadow: 0px 0px 3px rgba(0, 0, 0, 0.084), 0px 2px 3px rgba(0, 0, 0, 0.168);
}

.__UIV_SCOPE__ .form-container .social-button svg {
  width: 22px;
  height: 22px;
  fill: white;
}

.__UIV_SCOPE__ .form-container .social-button.facebook {
  background-color: #1778f2;
}

.__UIV_SCOPE__ .form-container .social-button.apple {
  background-color: #212121;
}

.__UIV_SCOPE__ .form-container .form {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.__UIV_SCOPE__ .form-container .form-group {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.__UIV_SCOPE__ .form-container .form-group label {
  display: block;
  margin-bottom: 5px;
}

.__UIV_SCOPE__ .form-container .form-group input[type="text"],
.__UIV_SCOPE__ .form-container .form-group input[type="password"] {
  width: 100%;
  padding: 12px 16px;
  border-radius: 6px;
  font-family: inherit;
  border: 1px solid #ccc;
}

.__UIV_SCOPE__ .form-container .form-group input::placeholder {
  opacity: 0.5;
}

.__UIV_SCOPE__ .form-container .form-group input[type="text"]:focus,
.__UIV_SCOPE__ .form-container .form-group input[type="password"]:focus {
  outline: none;
  border-color: #1778f2;
}

.__UIV_SCOPE__ .form-container .form-submit-btn {
  display: flex;
  justify-content: center;
  align-items: center;
  font-family: inherit;
  color: #fff;
  background-color: #212121;
  border: none;
  width: 100%;
  padding: 12px 16px;
  font-size: inherit;
  gap: 8px;
  margin: 12px 0;
  cursor: pointer;
  border-radius: 6px;
  box-shadow: 0px 0px 3px rgba(0, 0, 0, 0.084), 0px 2px 3px rgba(0, 0, 0, 0.168);
}

.__UIV_SCOPE__ .form-container .form-submit-btn:hover {
  background-color: #313131;
}

.__UIV_SCOPE__ .form-container .link {
  color: #1778f2;
  text-decoration: none;
}

.__UIV_SCOPE__ .form-container .forgot-password-link {
  align-self: flex-end;
  margin-top: -20px;
}

.__UIV_SCOPE__ .form-container .signup-link {
  align-self: center;
  font-weight: 500;
}

.__UIV_SCOPE__ .form-container .signup-link .link {
  font-weight: 400;
}

.__UIV_SCOPE__ .form-container .link:hover {
  text-decoration: underline;
}

.__UIV_SCOPE__ .form-container .line {
  width: 100%;
  height: 1px;
  background-color: #212121;
  opacity: 0.1;
}
